import { line } from 'axylo';

// A plain decimal string, the only kind of string Axylo itself would read as a number ('1438.75', '-2', '1e3').
// Anything else ('1,438.75', 'n/a', ' 984.5') is left exactly as sent, so Axylo reports it (AX106) instead of
// this code guessing what it meant.
const PLAIN_DECIMAL = /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/;

/** Revenue as a number when it is one or is written as a plain decimal; otherwise the value unchanged. */
function toNumber(value) {
  if (typeof value === 'string' && PLAIN_DECIMAL.test(value)) return Number(value);
  return value;
}

/**
 * The options `render` draws with, exported so they can be checked in Node with `validate('line', ...)`.
 *
 * - `revenue` arrives as a mix of numbers and decimal strings. Axylo converts a field only when every value is
 *   a string (`parse: 'number'`); in a mixed field it rejects every string, which would drop most days. So the
 *   strings are converted here, one row per input row, in the same order, so diagnostics' row numbers and
 *   `point.index` still refer to the caller's data.
 * - `day` is a UTC midnight per day. Declared `type: 'date'`, each is read as its UTC calendar day, the same in
 *   every time zone; without it, viewers west of UTC would see every value one day early.
 * - Rows may come in any order: a line is drawn in x order. A day with no row (2026-05-04 in data.json) is
 *   inferred from the regular daily step and drawn as a gap, never as zero or a straight line across it.
 */
export function chartOptions(data) {
  const rows = Array.isArray(data)
    ? data.map((row) => (row && typeof row === 'object' && 'revenue' in row
      ? { ...row, revenue: toNumber(row.revenue) }
      : row))
    : data;

  return {
    title: 'Daily store revenue',
    data: rows,
    x: { field: 'day', type: 'date' },
    y: {
      field: 'revenue',
      label: 'Revenue',
      // Amounts with cents: 984.5 reads 984.50. Display only; the drawn values are unchanged.
      format: { minimumFractionDigits: 2, maximumFractionDigits: 2 },
    },
  };
}

/** Draws the daily revenue line into `element` and returns the Axylo chart handle. */
export default function render(element, data) {
  return line(element, chartOptions(data));
}

