input.command:
node --input-type=module -e "
import { validate } from 'axylo';
import fs from 'node:fs';
import render, { chartOptions } from './chart.js';
const rows = JSON.parse(fs.readFileSync('data.json', 'utf8'));
const opts = chartOptions(rows);
console.log('default export is function:', typeof render === 'function', 'arity', render.length);
console.log('title:', opts.title);
console.log('rows (same order as input):');
for (const [i, r] of opts.data.entries()) console.log(' ', i, r.day, typeof r.revenue, r.revenue, '<- input', JSON.stringify(rows[i].revenue));
console.log('input untouched:', JSON.stringify(rows) === JSON.stringify(JSON.parse(fs.readFileSync('data.json','utf8'))));
const problems = validate('line', opts);
for (const d of problems) console.log(d.code, d.level, d.message);
const blocking = problems.filter(d => d.level !== 'hint');
if (blocking.length) { console.error('BLOCKING'); process.exit(1); }
console.log('Checked:', problems.length, 'diagnostics, none blocking.');
"

